<?php if ($invoices === []): ?><p class="empty"><?= e(__('empty.invoices')) ?></p><?php else: ?><div class="table-wrap"><table><thead><tr><th><?= e(__('fields.number')) ?></th><th><?= e(__('fields.status')) ?></th><th><?= e(__('fields.total')) ?></th><th><?= e(__('fields.due')) ?></th></tr></thead><tbody><?php foreach ($invoices as $row): ?><tr><td data-label="Number"><a href="<?= e(url('/portal/invoices/' . $row['id'])) ?>"><?= e($row['number']) ?></a></td><td data-label="Status"><?= e($row['status']) ?></td><td data-label="Total"><?= e(money($row['total'], $row['currency'])) ?></td><td data-label="Due"><?= e(money($row['amount_due'], $row['currency'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
